#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *g[] = {"Beta;Alpha;draw", "Beta;Gamma;win", "Alpha;Gamma;win"};
    char *s = tally(g, 3);
    assert(strstr(s, "Alpha                          |  2 |  1 |  1 |  0 |  4"));
    assert(strstr(s, "Alpha") < strstr(s, "Beta"));
    free(s);
    s = tally(NULL, 0);
    assert(!strcmp(s, "Team                           | MP |  W |  D |  L |  P"));
    free(s);
    {
        const char *values[] = {NULL};
        char *actual = tally(values, 0);
        assert(
            !strcmp(actual, "Team                           | MP |  W |  D |  L |  P"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;win"};
        char *actual = tally(values, 1);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nAllegoric Alaskans             |  1 |  1 |  0 |  0 |  "
                       "3\nBlithering Badgers             |  1 |  0 |  0 |  1 |  0"));
        free(actual);
    }
    {
        const char *values[] = {"Blithering Badgers;Allegoric Alaskans;loss"};
        char *actual = tally(values, 1);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nAllegoric Alaskans             |  1 |  1 |  0 |  0 |  "
                       "3\nBlithering Badgers             |  1 |  0 |  0 |  1 |  0"));
        free(actual);
    }
    {
        const char *values[] = {"Blithering Badgers;Allegoric Alaskans;win"};
        char *actual = tally(values, 1);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nBlithering Badgers             |  1 |  1 |  0 |  0 |  "
                       "3\nAllegoric Alaskans             |  1 |  0 |  0 |  1 |  0"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;draw"};
        char *actual = tally(values, 1);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nAllegoric Alaskans             |  1 |  0 |  1 |  0 |  "
                       "1\nBlithering Badgers             |  1 |  0 |  1 |  0 |  1"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;win",
                                "Allegoric Alaskans;Blithering Badgers;win"};
        char *actual = tally(values, 2);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nAllegoric Alaskans             |  2 |  2 |  0 |  0 |  "
                       "6\nBlithering Badgers             |  2 |  0 |  0 |  2 |  0"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;loss",
                                "Allegoric Alaskans;Blithering Badgers;win"};
        char *actual = tally(values, 2);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nAllegoric Alaskans             |  2 |  1 |  0 |  1 |  "
                       "3\nBlithering Badgers             |  2 |  1 |  0 |  1 |  3"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;win",
                                "Blithering Badgers;Courageous Californians;win",
                                "Courageous Californians;Allegoric Alaskans;loss"};
        char *actual = tally(values, 3);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nAllegoric Alaskans             |  2 |  2 |  0 |  0 |  "
                       "6\nBlithering Badgers             |  2 |  1 |  0 |  1 |  "
                       "3\nCourageous Californians        |  2 |  0 |  0 |  2 |  0"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;win",
                                "Devastating Donkeys;Courageous Californians;draw",
                                "Devastating Donkeys;Allegoric Alaskans;win",
                                "Courageous Californians;Blithering Badgers;loss",
                                "Blithering Badgers;Devastating Donkeys;loss",
                                "Allegoric Alaskans;Courageous Californians;win"};
        char *actual = tally(values, 6);
        assert(!strcmp(
            actual,
            "Team                           | MP |  W |  D |  L |  P\nDevastating "
            "Donkeys            |  3 |  2 |  1 |  0 |  7\nAllegoric Alaskans           "
            "  |  3 |  2 |  0 |  1 |  6\nBlithering Badgers             |  3 |  1 |  0 "
            "|  2 |  3\nCourageous Californians        |  3 |  0 |  1 |  2 |  1"));
        free(actual);
    }
    {
        const char *values[] = {"Allegoric Alaskans;Blithering Badgers;loss",
                                "Devastating Donkeys;Allegoric Alaskans;loss",
                                "Courageous Californians;Blithering Badgers;draw",
                                "Allegoric Alaskans;Courageous Californians;win"};
        char *actual = tally(values, 4);
        assert(!strcmp(
            actual,
            "Team                           | MP |  W |  D |  L |  P\nAllegoric "
            "Alaskans             |  3 |  2 |  0 |  1 |  6\nBlithering Badgers         "
            "    |  2 |  1 |  1 |  0 |  4\nCourageous Californians        |  2 |  0 |  "
            "1 |  1 |  1\nDevastating Donkeys            |  1 |  0 |  0 |  1 |  0"));
        free(actual);
    }
    {
        const char *values[] = {"Courageous Californians;Devastating Donkeys;win",
                                "Allegoric Alaskans;Blithering Badgers;win",
                                "Devastating Donkeys;Allegoric Alaskans;loss",
                                "Courageous Californians;Blithering Badgers;win",
                                "Blithering Badgers;Devastating Donkeys;draw",
                                "Allegoric Alaskans;Courageous Californians;draw"};
        char *actual = tally(values, 6);
        assert(!strcmp(
            actual,
            "Team                           | MP |  W |  D |  L |  P\nAllegoric "
            "Alaskans             |  3 |  2 |  1 |  0 |  7\nCourageous Californians    "
            "    |  3 |  2 |  1 |  0 |  7\nBlithering Badgers             |  3 |  0 |  "
            "1 |  2 |  1\nDevastating Donkeys            |  3 |  0 |  1 |  2 |  1"));
        free(actual);
    }
    {
        const char *values[] = {"Devastating Donkeys;Blithering Badgers;win",
                                "Devastating Donkeys;Blithering Badgers;win",
                                "Devastating Donkeys;Blithering Badgers;win",
                                "Devastating Donkeys;Blithering Badgers;win",
                                "Blithering Badgers;Devastating Donkeys;win"};
        char *actual = tally(values, 5);
        assert(!strcmp(actual,
                       "Team                           | MP |  W |  D |  L |  "
                       "P\nDevastating Donkeys            |  5 |  4 |  0 |  1 | "
                       "12\nBlithering Badgers             |  5 |  1 |  0 |  4 |  3"));
        free(actual);
    }
    return 0;
}
